#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    if (!(cin >> n)) return 0;
    cin >> s;
    // n should equal s.length(); ignore n.

    int ans = 0;
    for (char target = 'z'; target >= 'b'; --target) {
        bool changed = true;
        while (changed) {
            changed = false;
            int len = s.size();
            if (len == 0) break;
            // Find rightmost index i such that s[i] == target and it has a neighbor equal to target-1.
            int idx = -1;
            for (int i = len - 1; i >= 0; --i) {
                if (s[i] == target) {
                    char prevChar = char(target - 1);
                    bool ok = false;
                    if (i > 0 && s[i-1] == prevChar) ok = true;
                    if (i + 1 < len && s[i+1] == prevChar) ok = true;
                    if (ok) {
                        idx = i;
                        break;
                    }
                }
            }
            if (idx != -1) {
                s.erase(s.begin() + idx);
                ++ans;
                changed = true;
            }
        }
    }
    cout << ans << "\n";
    return 0;
}
